CREATE TABLE IF NOT EXISTS tb_myrep_pic_mapping_city (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  regional_name VARCHAR(120) NOT NULL,
  province_name VARCHAR(120) NOT NULL,
  city_name VARCHAR(120) NOT NULL,
  team_name VARCHAR(120) NULL,
  chief VARCHAR(120) NULL,
  rpm_area VARCHAR(30) NULL,
  sm_area VARCHAR(30) NULL,
  spv_area VARCHAR(30) NULL,
  snd_area VARCHAR(30) NULL,
  admin_area VARCHAR(30) NULL,
  snd_ho VARCHAR(30) NULL,
  atp_ho VARCHAR(30) NULL,
  rfs_ho VARCHAR(30) NULL,
  sitac_ho VARCHAR(30) NULL,
  dc_ho VARCHAR(30) NULL,
  qa_ho VARCHAR(30) NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_myrep_city (regional_name, province_name, city_name),
  KEY idx_myrep_city_lookup (city_name, province_name),
  KEY idx_myrep_region (regional_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
TRUNCATE TABLE tb_myrep_pic_mapping_city;
SELECT COUNT(*) AS total_rows FROM tb_myrep_pic_mapping_city;

